// All external text is untrusted. These checks cannot prove an AI claim true;
// every resulting draft requires human review before any communication.
const HEADER_CONTROL = /[\u0000-\u001f\u007f-\u009f]/u;
const BODY_CONTROL = /[\u0000-\u0008\u000b-\u001f\u007f-\u009f]/u;
const EMAIL = /^[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?(?:\.[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?)+$/u;
const isObject = value => !!value && typeof value === 'object' && !Array.isArray(value);
const field = (value, limit, required = true) => typeof value === 'string' && value.length <= limit && !HEADER_CONTROL.test(value) && (!required || value.trim().length > 0);
const issue = (code, message) => ({ code, message });
const allowed = value => value === true || (typeof value === 'string' && value.trim().toUpperCase() === 'TRUE');

// n8n's Code sandbox does not consistently expose the WHATWG URL global.
// These workflows need only fixed public HTTPS hosts and simple ASCII paths.
// Reject all URL features we do not need instead of implementing general URLs.
function parseHttpsUrl(value) {
  if (typeof value !== 'string' || HEADER_CONTROL.test(value) || /[\\\s%?#@]/u.test(value)) throw new Error('Unsupported URL');
  const match = /^https:\/\/([A-Za-z0-9.-]+)(\/[A-Za-z0-9_/:.-]*)?$/u.exec(value);
  if (!match || !match[1] || match[1].startsWith('.') || match[1].endsWith('.') || match[1].includes('..')) throw new Error('Invalid HTTPS URL');
  const hostname = match[1].toLowerCase();
  const pathname = match[2] || '/';
  if (pathname.includes('//') || /(?:^|\/)\.{1,2}(?:\/|$)/u.test(pathname)) throw new Error('Invalid path');
  return {protocol:'https:',hostname,pathname,href:'https://' + hostname + pathname,port:'',username:'',password:'',search:'',hash:''};
}

function prepareLead(row, config) {
  const issues = [];
  if (!isObject(row)) return { ok: false, status: 'blocked', lead: null, issues: [issue('invalid_row', 'Lead must be an object.')] };
  if (!isObject(config)) return { ok: false, status: 'blocked', lead: null, issues: [issue('invalid_config', 'Configuration must be an object.')] };
  const limits = { sellerName: 120, sellerCompany: 160, offer: 1000, model: 100 };
  for (const [key, limit] of Object.entries(limits)) {
    if (!field(config[key], limit)) issues.push(issue('invalid_config_' + key, 'Invalid ' + key + '.'));
  }
  if (!Number.isInteger(config.maxLeads) || config.maxLeads < 1 || config.maxLeads > 100) issues.push(issue('invalid_max_leads', 'maxLeads must be an integer from 1 to 100.'));
  const status = typeof row.status === 'string' ? row.status.trim().toLowerCase() : '';
  if (!['new', 'draft_ready', 'blocked'].includes(status)) issues.push(issue('invalid_status', 'Allowed statuses are new, draft_ready, and blocked.'));
  if (!allowed(row.contact_allowed)) issues.push(issue('contact_not_allowed', 'Explicit contact permission is required.'));
  for (const [key, limit] of Object.entries({ lead_id: 80, first_name: 100, company: 160, email: 254 })) {
    if (!field(row[key], limit)) issues.push(issue('invalid_' + key, 'Invalid ' + key + '.'));
  }
  if (field(row.lead_id, 80) && !/^[A-Za-z0-9][A-Za-z0-9_.:-]{0,79}$/u.test(row.lead_id.trim())) issues.push(issue('invalid_lead_id_format', 'lead_id must be a stable ASCII identifier.'));
  const email = typeof row.email === 'string' ? row.email.trim() : '';
  if (!EMAIL.test(email) || email.split('@')[0].length > 64 || email.split('@')[0].startsWith('.') || email.split('@')[0].endsWith('.') || email.split('@')[0].includes('..')) issues.push(issue('invalid_email_format', 'Email must be a single valid address.'));
  const notes = row.source_notes === undefined || row.source_notes === null ? '' : row.source_notes;
  if (typeof notes !== 'string' || notes.length > 3000 || BODY_CONTROL.test(notes)) issues.push(issue('invalid_source_notes', 'source_notes must be plain text within 3000 characters.'));
  let linkedinUrl = '';
  let linkedinHandle = '';
  if (row.linkedin_url !== undefined && row.linkedin_url !== null && row.linkedin_url !== '') {
    if (!field(row.linkedin_url, 250)) issues.push(issue('invalid_linkedin_url', 'LinkedIn URL is invalid.'));
    else {
      try {
        const parsed = parseHttpsUrl(row.linkedin_url.trim());
        const match = /^\/in\/([A-Za-z0-9][A-Za-z0-9_-]{0,99})\/?$/u.exec(parsed.pathname);
        if (parsed.protocol !== 'https:' || !['linkedin.com', 'www.linkedin.com'].includes(parsed.hostname) || parsed.port || parsed.username || parsed.password || parsed.search || parsed.hash || !match) throw new Error('invalid');
        linkedinHandle = match[1];
        linkedinUrl = 'https://www.linkedin.com/in/' + linkedinHandle + '/';
      } catch { issues.push(issue('invalid_linkedin_url', 'Use an HTTPS LinkedIn /in/ profile URL without query parameters.')); }
    }
  }
  let xUsername = '';
  if (row.x_username !== undefined && row.x_username !== null && row.x_username !== '') {
    if (!field(row.x_username, 16) || !/^@?[A-Za-z0-9_]{1,15}$/u.test(row.x_username.trim())) issues.push(issue('invalid_x_username', 'Use an X username, not a URL.'));
    else xUsername = row.x_username.trim().replace(/^@/u, '');
  }
  if (!linkedinUrl && !xUsername) issues.push(issue('missing_social_profile', 'At least one valid social profile is required.'));
  const lead = { lead_id: typeof row.lead_id === 'string' ? row.lead_id.trim() : '', first_name: typeof row.first_name === 'string' ? row.first_name.trim() : '', company: typeof row.company === 'string' ? row.company.trim() : '', email, linkedin_url: linkedinUrl, linkedin_handle: linkedinHandle, x_username: xUsername, source_notes: typeof notes === 'string' ? notes.trim() : '', contact_allowed: allowed(row.contact_allowed), status };
  const safeConfig = { sellerName: config.sellerName, sellerCompany: config.sellerCompany, offer: config.offer, model: config.model, maxLeads: config.maxLeads };
  if (issues.length) return { ok: false, status: 'blocked', lead, config: safeConfig, issues };
  if (status !== 'new') return { ok: false, status: 'skipped', lead, config: safeConfig, issues: [issue('already_processed', 'Only new leads are processed.')] };
  return { ok: true, status: 'research_ready', lead, config: safeConfig, issues: [] };
}

function linkedinPostUrl(value) {
  if (!field(value, 600)) return '';
  try {
    const url = parseHttpsUrl(value);
    if (url.protocol !== 'https:' || !['linkedin.com', 'www.linkedin.com'].includes(url.hostname) || url.username || url.password || url.port || url.search || url.hash || !/^\/(?:posts\/[A-Za-z0-9_-]+|feed\/update\/urn:li:activity:\d+)\/?$/u.test(url.pathname)) return '';
    return 'https://www.linkedin.com' + url.pathname;
  } catch { return ''; }
}

function normalizeResearch(lead, linkedinResponse, xResponse) {
  const issues = [];
  const evidence = [];
  if (!isObject(lead) || !lead.contact_allowed || !field(lead.email, 254) || !EMAIL.test(lead.email)) return { ok: false, status: 'needs_review', lead: null, evidence, issues: [issue('invalid_lead_context', 'Validated lead context is required.')], requires_human_review: true };
  const seen = new Set();
  function add(platform, records, prefix, makeUrl) {
    if (!Array.isArray(records)) { issues.push(issue('invalid_' + platform + '_response', 'Provider returned no valid record array.')); return; }
    let count = 0;
    for (const post of records.slice(0, 30)) {
      if (count === 3) break;
      if (!isObject(post) || typeof post.text !== 'string' || post.text.length > 10000 || BODY_CONTROL.test(post.text)) { issues.push(issue('invalid_' + platform + '_record', 'Provider record contains invalid text.')); continue; }
      const text = post.text.trim();
      const url = makeUrl(post);
      if (!text || !url) { issues.push(issue('invalid_' + platform + '_record', 'Provider record needs text and a valid source URL.')); continue; }
      if (seen.has(platform + ':' + text)) continue;
      seen.add(platform + ':' + text);
      count += 1;
      evidence.push({ id: prefix + count, platform, text: text.slice(0, 1500), url });
    }
  }
  if (lead.linkedin_url) {
    if (Array.isArray(linkedinResponse)) {
      const own = linkedinResponse.filter(post => isObject(post) && post.is_repost !== true && isObject(post.author) && typeof post.author.url === 'string' && post.author.url.replace(/\/$/u, '').toLowerCase() === lead.linkedin_url.replace(/\/$/u, '').toLowerCase());
      add('linkedin', own.map(post => ({text: post.text, url: post.share_url})), 'LI', post => linkedinPostUrl(post.url));
      if (own.length !== linkedinResponse.length) issues.push(issue('unverified_linkedin_author', 'Some LinkedIn records were reposts or did not match the requested profile.'));
    } else if (!isObject(linkedinResponse) || linkedinResponse.error || linkedinResponse.errors || linkedinResponse.ok === false) issues.push(issue('linkedin_provider_error', 'LinkedIn provider did not return usable data.'));
    else add('linkedin', linkedinResponse.posts, 'LI', post => linkedinPostUrl(post.url));
  }
  if (lead.x_username) {
    if (!isObject(xResponse) || xResponse.error || xResponse.errors || xResponse.ok === false) issues.push(issue('x_provider_error', 'X provider did not return usable data.'));
    else if (isObject(xResponse.user) && (xResponse.user.protected === true || (xResponse.user.username && String(xResponse.user.username).toLowerCase() !== lead.x_username.toLowerCase()))) issues.push(issue('x_identity_error', 'X profile identity does not match or is protected.'));
    else add('x', xResponse.data, 'X', post => typeof post.id === 'string' && /^\d{1,30}$/u.test(post.id) && (!post.author_id || (isObject(xResponse.user) && post.author_id === xResponse.user.id)) ? 'https://x.com/' + lead.x_username + '/status/' + post.id : '');
  }
  if (!evidence.length) issues.push(issue('no_evidence', 'No usable public source material was returned.'));
  return { ok: issues.length === 0 && evidence.length > 0, status: issues.length === 0 && evidence.length > 0 ? 'research_ready' : 'needs_review', lead, evidence, issues, requires_human_review: true };
}

function normalizeProvidedResearch(lead, row) {
  const empty = {ok:false,status:'needs_review',lead,evidence:[],issues:[],requires_human_review:true};
  if (!isObject(lead) || !lead.contact_allowed || !isObject(row)) return {...empty,issues:[issue('invalid_lead_context','Validated lead and source row are required.')]};
  const text = row.source_notes;
  if (typeof text !== 'string' || !text.trim() || text.length > 3000 || BODY_CONTROL.test(text)) return {...empty,issues:[issue('invalid_provided_text','Provide plain source text within 3000 characters.')]};
  if (!field(row.source_url,600)) return {...empty,issues:[issue('invalid_source_url','Provide a public source URL.') ]};
  let url;
  try { url = parseHttpsUrl(row.source_url.trim()); } catch { return {...empty,issues:[issue('invalid_source_url','Source URL is invalid.')]}; }
  if (url.protocol !== 'https:' || url.username || url.password || url.port || url.search || url.hash) return {...empty,issues:[issue('invalid_source_url','Source URL must be HTTPS without credentials or query parameters.')]};
  let platform = '';
  if (['linkedin.com','www.linkedin.com'].includes(url.hostname) && lead.linkedin_url) {
    const ownProfile = url.pathname.replace(/\/$/u,'').toLowerCase() === '/in/' + lead.linkedin_handle.toLowerCase();
    const ownPost = url.pathname.toLowerCase().startsWith('/posts/' + lead.linkedin_handle.toLowerCase() + '_') && !!linkedinPostUrl(url.href);
    if (ownProfile || ownPost) platform = 'linkedin';
  } else if (['x.com','www.x.com'].includes(url.hostname) && lead.x_username) {
    const match = /^\/([A-Za-z0-9_]{1,15})\/status\/(\d{1,30})\/?$/u.exec(url.pathname);
    if (match && match[1].toLowerCase() === lead.x_username.toLowerCase()) platform = 'x';
  }
  if (!platform) return {...empty,issues:[issue('source_identity_mismatch','Source URL must belong to the validated LinkedIn or X profile.')]};
  return {...empty,ok:true,status:'research_ready',issues:[],evidence:[{id:platform === 'x' ? 'X1' : 'LI1',platform,text:text.trim().slice(0,1500),url:url.href}]};
}

function validateDraft(context, response) {
  const base = { ok: false, status: 'needs_review', lead: isObject(context) ? context.lead : null, subject: '', body: '', evidence_ids: [], issues: [], requires_human_review: true };
  const reject = (code, message) => ({ ...base, issues: [issue(code, message)] });
  if (!isObject(context) || context.ok !== true || !isObject(context.lead) || !context.lead.contact_allowed || !Array.isArray(context.evidence) || !context.evidence.length) return reject('missing_verified_context', 'Usable research and explicit permission are required.');
  const validIds = new Set();
  for (const item of context.evidence) {
    if (!isObject(item) || typeof item.id !== 'string' || !/^(?:LI|X)[1-3]$/u.test(item.id) || validIds.has(item.id) || typeof item.text !== 'string' || !field(item.text.replace(/\n/gu, ''), 1500) || typeof item.url !== 'string') return reject('invalid_evidence_context', 'Evidence context is malformed.');
    validIds.add(item.id);
  }
  if (!isObject(response) || response.error || response.errors || response.ok === false) return reject('model_error', 'Model response indicates a failure.');
  let result = response;
  if (Object.prototype.hasOwnProperty.call(response, 'choices')) {
    if (!Array.isArray(response.choices) || !response.choices.length || !isObject(response.choices[0])) return reject('invalid_model_response', 'Chat completion response is missing a choice.');
    const choice = response.choices[0];
    if (choice.finish_reason !== 'stop') return reject('incomplete_model_response', 'Completion did not finish normally.');
    if (!isObject(choice.message) || choice.message.refusal || typeof choice.message.content !== 'string') return reject('model_refusal', 'Model refused or returned no text content.');
    if (choice.message.content.length > 10000) return reject('oversize_model_response', 'Model response exceeds size limit.');
    try { result = JSON.parse(choice.message.content); } catch { return reject('invalid_json', 'Model response is not strict JSON.'); }
  }
  if (!isObject(result)) return reject('invalid_draft', 'Draft must be an object.');
  const keys = Object.keys(result).sort().join(',');
  if (keys !== 'body,evidence_ids,subject') return reject('invalid_draft_schema', 'Draft must contain only subject, body, and evidence_ids.');
  if (!field(result.subject, 120) || result.subject.trim().length < 3) return reject('invalid_subject', 'Subject must be plain single-line text from 3 to 120 characters.');
  if (typeof result.body !== 'string' || result.body.length > 800 || result.body.trim().length < 20 || BODY_CONTROL.test(result.body)) return reject('invalid_body', 'Body must be plain text from 20 to 800 characters with LF newlines only.');
  if (/<\/?[A-Za-z][^>]*>/u.test(result.body) || /<\/?[A-Za-z][^>]*>/u.test(result.subject)) return reject('html_not_allowed', 'Draft must contain plain text, not HTML.');
  if (!Array.isArray(result.evidence_ids) || result.evidence_ids.length < 1 || result.evidence_ids.length > 6 || result.evidence_ids.some(id => typeof id !== 'string' || !validIds.has(id)) || new Set(result.evidence_ids).size !== result.evidence_ids.length) return reject('invalid_citations', 'Every citation must be a unique evidence ID from this lead.');
  return { ...base, ok: true, status: 'draft_ready', subject: result.subject.trim(), body: result.body.trim(), evidence_ids: [...result.evidence_ids], issues: [] };
}

function buildDemoRows() {
  return [
    { lead_id: 'DEMO-001', first_name: 'Morgan', company: 'Example Supply', email: 'user@example.com', linkedin_url: 'https://www.linkedin.com/in/example-morgan/', x_username: 'example_morgan', status: 'new', contact_allowed: 'TRUE', source_notes: 'Synthetic demonstration record. Replace before real research.' },
    { lead_id: 'DEMO-002', first_name: 'Sam', company: 'Example Studio', email: 'user@example.com', linkedin_url: '', x_username: 'example_sam', status: 'new', contact_allowed: 'FALSE', source_notes: 'Synthetic record intentionally blocked by missing permission.' },
  ];
}


return buildDemoRows().map(row=>({json:row}));

